import { readFile, writeFile } from "node:fs/promises";
import { pathToFileURL } from "node:url";
import { getCompatibilitySummary } from "../lib/game-compatibility.mjs";

export function renderCompatibilityDocs(data) {
  const summary = getCompatibilitySummary(data.entries);
  const date = new Intl.DateTimeFormat("en-GB", { day: "numeric", month: "long", year: "numeric", timeZone: "UTC" }).format(new Date(data.recordedOn));
  return `# Game testing

<!-- Generated by scripts/generate-compatibility-docs.mjs. Edit data/game-compatibility.json. -->

As of **${date}**, ScummWEB has checked ${summary.checked} editions across
${summary.checkedGames} games.

| Startup result | Editions |
| --- | ---: |
| Verified | ${summary.verified} |
| With warnings | ${summary.warnings} |
| Failed | ${summary.failed} |

Startup checks cover a screen, menu, original prompt, or opening scene.
Warnings and failures describe ScummVM or ScummWEB issues. Results apply
to the tested edition and cover startup only.

Search [Game compatibility](https://scummweb.tsilva.eu/compatibility) for
editions, observations, and earlier checks. The
[repository data](../data/game-compatibility.json) preserves the full
records and lists ${summary.untested} games without a recorded check.
Their upstream ratings come from the
[ScummVM ${data.upstreamReference.version} compatibility chart](${data.upstreamReference.url}).
See [how to record a result](maintaining-scummweb.md#maintaining-game-compatibility).
`;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const data = JSON.parse(await readFile(new URL("../data/game-compatibility.json", import.meta.url), "utf8"));
  const output = new URL("../docs/game-testing.md", import.meta.url);
  const markdown = renderCompatibilityDocs(data);
  if (process.argv.includes("--check")) {
    if (await readFile(output, "utf8") !== markdown) {
      throw new Error("Compatibility docs are stale. Run node scripts/generate-compatibility-docs.mjs.");
    }
  } else {
    await writeFile(output, markdown);
  }
}
